/**
 * src/app/layout.tsx — Root Layout (V4.2)
 *
 * - ThemeScript inséré dans <head> AVANT l'hydratation → zéro flash visuel (FOUC)
 * - Polices via next/font/google : Cormorant (serif) + Montserrat (sans-serif)
 * - Variables CSS des polices alignées avec tailwind.config.ts
 * - lang="fr" + suppressHydrationWarning (requis par ThemeScript)
 * - Métadonnées lues depuis site.config.ts — aucun nom écrit en dur
 */

import type { Metadata, Viewport } from "next";
import { Cormorant, Montserrat } from "next/font/google";
import { ThemeScript } from "@/components/ThemeToggle";
import { siteConfig } from "../../site.config";
import "./globals.css";

// ── Polices ──────────────────────────────────────────────────────────────────

const cormorant = Cormorant({
  subsets: ["latin"],
  variable: "--font-cormorant",
  display: "swap",
  weight: ["300", "400", "500", "600"],
});

const montserrat = Montserrat({
  subsets: ["latin"],
  variable: "--font-montserrat",
  display: "swap",
  weight: ["300", "400", "500", "600", "700"],
});

// ── Métadonnées ───────────────────────────────────────────────────────────────

export const metadata: Metadata = {
  title: {
    default: siteConfig.nomCommercial,
    template: `%s — ${siteConfig.nomCommercial}`,
  },
  description: siteConfig.descriptionPartage,
  metadataBase: new URL(
    siteConfig.siteUrl.startsWith("[À COMPLÉTER")
      ? "http://localhost:3000"
      : siteConfig.siteUrl
  ),
  openGraph: {
    type: "website",
    locale: siteConfig.langue,
    siteName: siteConfig.nomCommercial,
    title: siteConfig.nomCommercial,
    description: siteConfig.descriptionPartage,
  },
  robots: {
    index: process.env.NODE_ENV === "production",
    follow: process.env.NODE_ENV === "production",
  },
  alternates: {
    canonical: "/",
  },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  viewportFit: "cover", // safe areas iOS
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#FAFAF9" },
    { media: "(prefers-color-scheme: dark)", color: "#1C1917" },
  ],
};

// ── Layout ────────────────────────────────────────────────────────────────────

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html
      lang="fr"
      suppressHydrationWarning
      // La classe "dark" est injectée par ThemeScript avant l'hydratation
    >
      <head>
        {/*
          ThemeScript : script minimal exécuté avant le rendu React.
          Lit localStorage → applique la classe "dark" sur <html> si nécessaire.
          Neutralise le flash de mauvais thème au chargement (FOUC).
          Doit être placé AVANT tout CSS ou composant qui dépend du thème.
        */}
        <ThemeScript />
      </head>
      <body
        className={`${cormorant.variable} ${montserrat.variable} bg-background text-primary font-sans antialiased`}
      >
        {children}
      </body>
    </html>
  );
}
